function showView(name) {
  document.querySelectorAll('.view').forEach(function(v){v.classList.remove('active');});
  document.querySelectorAll('.bnbtn').forEach(function(b){b.classList.remove('active');});
  document.getElementById('view-'+name).classList.add('active');
  var b = document.getElementById('bnav-'+name);
  if(b) b.classList.add('active');
}

function switchTab(tab) {
  document.getElementById('ftab-foryou').classList.toggle('active', tab==='foryou');
  document.getElementById('ftab-following').classList.toggle('active', tab==='following');
  document.getElementById('feed-foryou').style.display = tab==='foryou' ? '' : 'none';
  document.getElementById('feed-following').style.display = tab==='following' ? '' : 'none';
}

