function buildCard(pid, avHtml, uname, loc, imgHtml, likes, cap, time, onImg) {
  var h = '<div class="post-card">';
  h += '<div class="post-hdr"><div class="post-av-wrap"><div class="post-av">'+avHtml+'</div></div>';
  h += '<div style="flex:1"><div class="post-uname">'+uname+'</div><div class="post-loc">'+loc+'</div></div>';
  h += '<div class="post-more">\u22EF</div></div>';
  h += '<div class="post-img-wrap" onclick="'+onImg+'">'+imgHtml+'</div>';
  h += '<div class="post-actions">';
  h += '<button class="pabtn" id="heart_'+pid+'" onclick="toggleFeedLike(this,\''+pid+'\','+likes+')">'+svgHeart()+'</button>';
  h += '<button class="pabtn">'+svgCmt()+'</button>';
  h += '<button class="pabtn">'+svgShare()+'</button>';
  h += '<div class="sp"></div>';
  h += '<button class="pabtn">'+svgSave()+'</button></div>';
  h += '<div class="post-likes" id="likes_'+pid+'">'+likes.toLocaleString('de-DE')+' Gef\u00E4llt mir</div>';
  h += '<div class="post-cap">'+cap+'</div>';
  h += '<div class="post-time">'+time+'</div>';
  h += '<div class="post-cmt"><span>\uD83D\uDE42</span><input type="text" placeholder="Kommentar hinzuf\u00FCgen \u2026"><button class="pb">Posten</button></div>';
  h += '</div>';
  return h;
}

function catImgTag(src, n, cls) {
  var t = '<img src="'+src+'" data-n="'+n+'" alt="Katze" loading="lazy"';
  if(cls) t += ' class="'+cls+'"';
  return t+'>';
}

function renderCatStories() {
  var h = '<div class="story"><div class="story-ring" style="background:linear-gradient(45deg,#405de6,#5851db,#833ab4)"><div class="story-av"><span style="font-size:20px">\uD83D\uDCDA</span></div></div><div class="story-name">Meine Story</div></div>';
  for(var i=0;i<catAccounts.length;i++){
    var a=catAccounts[i]; var s=i>3?' seen':'';
    h+='<div class="story"><div class="story-ring'+s+'"><div class="story-av">'+catImgTag(CAT_THUMB+a.lock,i,'')+'</div></div><div class="story-name">'+a.handle.split('_')[0]+'</div></div>';
  }
  document.getElementById('cat-stories').innerHTML=h;
}

function renderCatPosts() {
  var h='';
  for(var i=0;i<12;i++){
    var a=catAccounts[i%catAccounts.length]; var pid='cat_'+i;
    var av=catImgTag(CAT_THUMB+a.lock,i,'');
    var img=catImgTag(CAT_BASE+(i+1),i,'');
    h+=buildCard(pid,av,a.handle,'\uD83C\uDF0E Deutschland',img,catLikes[i],catCaps[i],catTimes[i],'openCatModal('+i+')');
  }
  document.getElementById('cat-posts').innerHTML=h;
}

function renderLitStories() {
  var keys=Object.keys(litAccounts); var h='';
  for(var i=0;i<keys.length;i++){
    var a=litAccounts[keys[i]];
    h+='<div class="story" onclick="openAcc(\''+keys[i]+'\')"><div class="story-ring"><div class="story-av"><span style="font-size:20px">'+a.emoji+'</span></div></div><div class="story-name">'+keys[i]+'</div></div>';
  }
  document.getElementById('lit-stories').innerHTML=h;
}

function renderLitPosts() {
  var h='';
  for(var i=0;i<litPosts.length;i++){
    var p=litPosts[i]; var pid='lit_'+p.id;
    var av='<span style="font-size:13px">\uD83D\uDCDA</span>';
    var img='<div style="width:100%;height:100%;background:#1C1E2D;">'+p.html+'</div>';
    h+=buildCard(pid,av,p.uname,p.loc,img,p.likes,p.cap,p.time,'openLitModal('+i+')');
  }
  document.getElementById('lit-posts').innerHTML=h;
}

